//! `sort: "relevance"`: declarations, generated files, coverage of alternation words.

use super::*;

/// A hit on a line past [`crate::security::LONG_LINE_BYTES`] shows a window of
/// the line, but its rank and byte offset are the whole line's: a hit deep in
/// a long comment ranks as prose, at the hit's own byte.
#[test]
fn a_windowed_long_line_row_ranks_and_offsets_as_its_whole_line() {
    let t = TmpDir::new();
    let filler = "x".repeat(crate::security::LONG_LINE_BYTES + 1);
    let line = format!("// {filler} needle\n");
    t.write("min.rs", &line);
    let mut o = opts(t.path(), "needle");
    // Context lines keep the row on the assembled (not deferred) path.
    o.context = crate::types::SearchContext::symmetric(1);
    let r = search(o).expect("ok");
    let hit = &r.files[0].matches[0];
    assert!(
        hit.value.len() < line.len(),
        "the row is a window of the line"
    );
    assert_eq!(hit.byte_offset as usize, filler.len() + 4);
    assert_eq!(hit.rank, Some(0), "a hit in a comment ranks as prose");
}

#[test]
fn relevance_orders_by_source_path_then_count_then_line_weight_then_path() {
    let t = TmpDir::new();
    t.write("a_comment.rs", "// needle here\n");
    t.write("b_decl.rs", "fn needle() {}\n");
    t.write("c_tests/x_test.rs", "fn needle() {}\n");
    t.write("d_two.rs", "// needle\n// needle\n");
    // A pattern (not a bare identifier) ranks by density first.
    let mut o = opts(t.path(), "ne+dle");
    o.sort = SearchSort::Relevance;
    let r = search(o.clone()).expect("ok");
    let names = r
        .files
        .iter()
        .map(|f| f.path.rsplit('/').next().unwrap_or_default().to_owned())
        .collect::<Vec<_>>();
    assert_eq!(
        names,
        ["d_two.rs", "b_decl.rs", "a_comment.rs", "x_test.rs"]
    );
    // Path-list views: source paths first, then path.
    o.output = SearchOutput::FilesWithMatch;
    let r = search(o).expect("ok");
    let names = r
        .files
        .iter()
        .map(|f| f.path.rsplit('/').next().unwrap_or_default().to_owned())
        .collect::<Vec<_>>();
    assert_eq!(
        names,
        ["a_comment.rs", "b_decl.rs", "d_two.rs", "x_test.rs"]
    );
}

/// A generated file (by its header or path) ranks after every hand-written
/// file, and a test file after every source file, however many hits it holds.
#[test]
fn relevance_ranks_generated_files_after_hand_written_ones() {
    let t = TmpDir::new();
    t.write(
        "commands.def",
        "/* Automatically generated by generate-command-code.py, do not edit. */\nneedle\nneedle\nneedle\n",
    );
    t.write("api.generated.ts", "needle\nneedle\n");
    t.write("src/one.c", "x = needle;\n");
    t.write("tests/two_test.c", "needle;\nneedle;\n");
    let mut o = opts(t.path(), "ne+dle");
    o.sort = SearchSort::Relevance;
    let r = search(o.clone()).expect("ok");
    let names = r
        .files
        .iter()
        .map(|f| f.path.rsplit('/').next().unwrap_or_default().to_owned())
        .collect::<Vec<_>>();
    assert_eq!(
        names,
        ["one.c", "two_test.c", "commands.def", "api.generated.ts"]
    );
    // Every hit is still returned; only the order changes.
    let total: usize = r.files.iter().map(|f| f.matches.len()).sum();
    assert_eq!(total, 8);
    o.sort = SearchSort::Path;
    let by_path = search(o).expect("ok");
    assert_eq!(by_path.files.len(), 4);
}

/// An identifier search asks where a name lives: a source file declaring it
/// ranks before denser call sites, tests, and comments. A test file declaring
/// the name keeps the ordinary density order.
#[test]
fn identifier_search_ranks_the_declaring_source_file_first() {
    let t = TmpDir::new();
    t.write("a_calls.ts", "newElementWith(el);\n".repeat(9));
    t.write(
        "b_tests/x.test.ts",
        "export const newElementWith = 1;\nnewElementWith();\n",
    );
    t.write(
        "z_src/mutate.ts",
        "export const newElementWith = <T>(el: T) => el;\n",
    );
    t.write(
        "y_src/MoreObjects.java",
        "  public static <T> T newElementWith(@Nullable T first) {\n",
    );
    let names = |pattern: &str, fixed: bool| {
        let mut o = opts(t.path(), pattern);
        o.sort = SearchSort::Relevance;
        o.syntax = if fixed {
            PatternSyntax::Literal
        } else {
            PatternSyntax::Regex
        };
        o.whole_word = Some(fixed);
        search(o)
            .expect("ok")
            .files
            .iter()
            .map(|f| f.path.rsplit('/').next().unwrap_or_default().to_owned())
            .collect::<Vec<_>>()
    };
    for fixed in [false, true] {
        assert_eq!(
            names("newElementWith", fixed),
            ["MoreObjects.java", "mutate.ts", "a_calls.ts", "x.test.ts"],
            "fixed {fixed}"
        );
    }
    // Any regex beyond a bare identifier ranks source files by count, then
    // tests.
    assert_eq!(
        names("newElementWith\\b", false),
        ["a_calls.ts", "MoreObjects.java", "mutate.ts", "x.test.ts"]
    );
}

/// The relevance rank reads the generated-file header from the bytes the
/// search read, so a header past the first read buffer is still the file's
/// first bytes, and a short file is judged whole.
#[test]
fn relevance_reads_the_generated_header_from_the_searched_bytes() {
    let t = TmpDir::new();
    t.write("short.c", "// @generated\nneedle\n");
    t.write(
        "long.c",
        format!(
            "// Code generated by x. DO NOT EDIT.\n{}",
            "needle\n".repeat(40_000)
        ),
    );
    t.write("hand.c", "needle\n");
    let mut options = opts(t.path(), "needle");
    options.sort = SearchSort::Relevance;
    let result = search(options).expect("search");
    let names = result
        .files
        .iter()
        .map(|file| {
            Path::new(&file.path)
                .file_name()
                .unwrap()
                .to_string_lossy()
                .into_owned()
        })
        .collect::<Vec<_>>();
    assert_eq!(
        names.first().map(String::as_str),
        Some("hand.c"),
        "{names:?}"
    );
    assert_eq!(names.len(), 3);
}

/// `.gitattributes` `linguist-generated`/`linguist-vendored` mark a file
/// generated for the relevance rank, as git resolves them: the deepest
/// attributes file first, its last matching line deciding, `-attr` unsetting.
#[test]
fn relevance_ranks_gitattributes_generated_files_last() {
    let t = TmpDir::new();
    t.write(".git/HEAD", "ref: refs/heads/main\n");
    t.write(
        ".gitattributes",
        "gen/** linguist-generated=true\nlib/*.ts linguist-generated\nthird/** linguist-vendored\n",
    );
    t.write("lib/.gitattributes", "keep.ts -linguist-generated\n");
    t.write("gen/api.ts", "needle\n".repeat(9));
    t.write("lib/out.ts", "needle\n".repeat(8));
    t.write("third/dep.ts", "needle\n".repeat(7));
    t.write("lib/keep.ts", "needle\nneedle\n");
    t.write("src/a.ts", "needle\n");
    let mut options = opts(t.path(), "needle");
    options.sort = SearchSort::Relevance;
    let result = search(options).expect("search");
    let names: Vec<String> = result
        .files
        .iter()
        .map(|file| {
            Path::new(&file.path)
                .strip_prefix(t.path())
                .unwrap_or(Path::new(&file.path))
                .to_string_lossy()
                .replace('\\', "/")
        })
        .collect();
    assert_eq!(
        names,
        [
            "lib/keep.ts",
            "src/a.ts",
            "gen/api.ts",
            "lib/out.ts",
            "third/dep.ts"
        ],
        "{names:?}"
    );
}

/// For a word alternation (`retry|backoff|jitter`), a file holding more of
/// its words outranks one repeating a single common word, then hit count
/// decides. Other searches keep the count order.
#[test]
fn relevance_ranks_alternation_coverage_before_hit_count() {
    let t = TmpDir::new();
    t.write("flood.rs", "retry\n".repeat(40));
    t.write("all.rs", "retry\nbackoff\nJitter\n");
    t.write("two.rs", "retry\nretry\nbackoff\n");
    let rank = |pattern: &str| {
        let mut options = opts(t.path(), pattern);
        options.sort = SearchSort::Relevance;
        search(options)
            .expect("search")
            .files
            .iter()
            .map(|file| {
                Path::new(&file.path)
                    .file_name()
                    .unwrap()
                    .to_string_lossy()
                    .into_owned()
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(
        rank("retry|backoff|jitter"),
        ["all.rs", "two.rs", "flood.rs"]
    );
    assert_eq!(
        rank(r"\b(retry|backoff|jitter)\b"),
        ["all.rs", "two.rs", "flood.rs"]
    );
    assert_eq!(rank("retry"), ["flood.rs", "two.rs", "all.rs"]);
}

/// A file the caller's [`crate::types::TestCodeRank`] names test code (a module
/// mounted only under test, which no spelling shows) ranks after the source
/// file declaring the same name, as a test file by its path does.
#[test]
fn relevance_ranks_a_caller_named_test_file_after_the_source_declaration() {
    let t = TmpDir::new();
    t.write("a_support.rs", "fn needle() {}\n");
    t.write("b_source.rs", "pub fn needle() {}\n");
    let mut o = opts(t.path(), "needle");
    o.sort = SearchSort::Relevance;
    let names = |o: &TextSearchOptions| {
        search(o.clone())
            .expect("ok")
            .files
            .iter()
            .map(|f| f.path.rsplit('/').next().unwrap_or_default().to_owned())
            .collect::<Vec<_>>()
    };
    assert_eq!(
        names(&o),
        ["a_support.rs", "b_source.rs"],
        "path order alone"
    );
    o.test_code_rank = Some(crate::types::TestCodeRank {
        test_path: Arc::new(|path: &Path| path.ends_with("a_support.rs")),
        spans: Arc::new(|_| Arc::new(Vec::new())),
    });
    assert_eq!(names(&o), ["b_source.rs", "a_support.rs"]);
}

/// The callback's span verdict is shared by every matched row of a file.
/// Test density/declaring hits never inflate a mixed file's source rank.
#[test]
fn relevance_inline_spans_preserve_counts_and_source_priority() {
    let t = TmpDir::new();
    t.write("a_mixed.rs", "fn run() { needle(); }\n#[cfg(test)]\nmod checks {\n    fn needle() {}\n    fn check() {\n        needle();\n        needle();\n    }\n}\n");
    t.write(
        "b_two.rs",
        "fn first() { needle(); }\nfn second() { needle(); }\n",
    );
    t.write("c_source.rs", "pub fn needle() {}\n");
    t.write("d_inline.rs", "pub fn other() {}\n#[cfg(test)]\nmod checks {\n    fn needle() {}\n    fn check() {\n        needle();\n        needle();\n    }\n}\n");
    t.write("e_unmatched.rs", "pub fn other() {}\n");
    for (values, context) in [
        (SourceValues::Owned, crate::types::SearchContext::default()),
        (
            SourceValues::Deferred,
            crate::types::SearchContext::default(),
        ),
        (
            SourceValues::Owned,
            crate::types::SearchContext::symmetric(1),
        ),
    ] {
        let reads = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let counted = Arc::clone(&reads);
        let mut options = opts(t.path(), "needle");
        options.sort = SearchSort::Relevance;
        options.values = values;
        options.context = context;
        options.test_code_rank = Some(crate::types::TestCodeRank {
            test_path: Arc::new(|_| false),
            spans: Arc::new(move |path| {
                counted.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                Arc::new(
                    if path.ends_with("a_mixed.rs") || path.ends_with("d_inline.rs") {
                        vec![[2, 9]]
                    } else {
                        Vec::new()
                    },
                )
            }),
        });
        let result = search(options.clone()).expect("search");
        let names = |result: &TextSearchResult| {
            result
                .files
                .iter()
                .map(|file| {
                    Path::new(&file.path)
                        .file_name()
                        .expect("name")
                        .to_string_lossy()
                        .into_owned()
                })
                .collect::<Vec<_>>()
        };
        assert_eq!(
            names(&result),
            ["c_source.rs", "b_two.rs", "a_mixed.rs", "d_inline.rs"]
        );
        assert_eq!(
            result
                .files
                .iter()
                .map(|file| file.match_count)
                .collect::<Vec<_>>(),
            [1, 2, 4, 3],
            "full counts unchanged"
        );
        assert_eq!(
            reads.load(std::sync::atomic::Ordering::Relaxed),
            result.files.len(),
            "one span read per matched file; none for the unmatched file"
        );
        let mixed = &result.files[2];
        let production = mixed
            .matches
            .iter()
            .find(|hit| hit.line == 1)
            .expect("source hit");
        let declaration = mixed
            .matches
            .iter()
            .find(|hit| hit.line == 4)
            .expect("test declaration");
        assert!(
            production.rank > declaration.rank,
            "source code precedes a test declaration"
        );
        assert!(
            declaration.is_declaration(),
            "ranking preserves declaration identity"
        );
        options.sort_reverse = Some(true);
        let reverse = search(options.clone()).expect("reverse");
        let mut expected = names(&result);
        expected.reverse();
        assert_eq!(names(&reverse), expected);
        let before_path = reads.load(std::sync::atomic::Ordering::Relaxed);
        options.sort = SearchSort::Path;
        options.sort_reverse = None;
        assert_eq!(
            names(&search(options).expect("path")),
            ["a_mixed.rs", "b_two.rs", "c_source.rs", "d_inline.rs"]
        );
        assert_eq!(
            reads.load(std::sync::atomic::Ordering::Relaxed),
            before_path,
            "path sort does not read inline spans"
        );
    }
}
